{
  "name": "mem0-collector",
  "version": "0.7.0",
  "description": "OpenCode plugin for automatic memory collection via Mem0 MCP server",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    }
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "mem0"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/anomalyco/mem0-collector"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.4.0",
    "@opencode-ai/sdk": ">=1.4.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0",
    "@opencode-ai/sdk": ">=1.4.0"
  }
}

import { createOpencodeClient } from "@opencode-ai/sdk";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import path from "path";

const MEM0_USER_ID = process.env.MEM0_USER_ID || "default";
const MEM0_AGENT_ID = process.env.MEM0_AGENT_ID || "opencode";

const DATA_DIR = path.join(process.env.HOME || "/root", ".local/share/opencode/mem0-collector");
const STORE_FILE = path.join(DATA_DIR, "store.json");
const SYNC_DIR = path.join(DATA_DIR, "pending_sync");

function ensureDir(dir) {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

function readStore() {
  ensureDir(DATA_DIR);
  try {
    return JSON.parse(readFileSync(STORE_FILE, "utf-8"));
  } catch {
    return {};
  }
}

function writeStore(store) {
  ensureDir(DATA_DIR);
  writeFileSync(STORE_FILE, JSON.stringify(store, null, 2), "utf-8");
}

function writePendingSync(text, userId, agentId, sessionId, categories) {
  ensureDir(SYNC_DIR);
  const entry = {
    text,
    userId,
    agentId,
    sessionId,
    categories,
    timestamp: new Date().toISOString(),
  };
  const filename = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}.json`;
  writeFileSync(
    path.join(SYNC_DIR, filename),
    JSON.stringify(entry, null, 2),
    "utf-8"
  );
}

function localKey(userId, agentId) {
  return `${userId}:${agentId}`;
}

function storeLocal(text, userId, agentId, sessionId, metadata, categories) {
  const store = readStore();
  const key = localKey(userId, agentId);
  if (!store[key]) store[key] = [];
  store[key].push({
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    text,
    timestamp: new Date().toISOString(),
    sessionId: sessionId || "",
    metadata: metadata || {},
    categories: categories || [],
  });
  writeStore(store);
}

async function fetchSessionTitle(sessionID) {
  try {
    const client = createOpencodeClient();
    const session = await client.sessions.info({ id: sessionID });
    return session?.title || "";
  } catch {
    return "";
  }
}

function storeMemory(text, userId, agentId, sessionId, categories) {
  storeLocal(text, userId, agentId, sessionId, {}, categories);
  writePendingSync(text, userId, agentId, sessionId, categories);
}

export const Mem0CollectorPlugin = async () => {
  console.log("[mem0-collector] Initialized (auto-collect + pending sync queue)");

  return {
    event: async (event) => {
      if (event.type === "session.compacted") {
        const sessionID = event.properties.sessionID;
        const title = await fetchSessionTitle(sessionID);
        const text = title
          ? `Session summary: ${title}`
          : `Session was compacted (ID: ${sessionID})`;
        storeMemory(text, MEM0_USER_ID, MEM0_AGENT_ID, sessionID, ["session_summary", "automated"]);
      }

      if (event.type === "session.updated") {
        const info = event.properties.info;
        if (info?.title) {
          storeMemory(
            `Session: ${info.title}`,
            MEM0_USER_ID,
            MEM0_AGENT_ID,
            info.id,
            ["session", "automated"]
          );
        }
      }
    },
  };
};

export default Mem0CollectorPlugin;
